            ASSAY_PARTY_NOT_THE_SETTLING_PARTY: 'Assay {0} is {1}\u2019s result, but this contract settles on {2}\u2019s. An umpire result may always settle; any other party\u2019s may not.',
            RESULTS_IN_DISPUTE: 'Assays {0} and {1} disagree by {2} percentage points, and this contract states no splitting limit. State a limit on the contract, or record an umpire result and settle on that \u2014 the system will not choose whose number is money.',
            RESULTS_EXCEED_SPLITTING_LIMIT: 'Assays {0} and {1} disagree by {2} percentage points, beyond the {3} the contract allows. Under that contract this goes to a third-party lab, and the umpire result settles it.',
