        entryLink: 'Counterparty overlap',
        what: 'One company can legitimately be both a supplier and a customer \u2014 in this trade that is normal, not an anomaly. Suppliers and customers are two unrelated tables here, so this page reports where the same company appears on both sides. It reports; it does not join them.',
        notNettedTitle: 'The two exposures are shown side by side and are deliberately NOT added together.',
        notNettedWhy: 'Netting is a legal act, not an arithmetic one. Offsetting what you owe against what you are owed requires a set-off right, which lives in a contract \u2014 and no such contract is recorded in this system. Jurisdictions also differ on whether set-off survives the other side going insolvent. Adding these two figures silently would understate receivables and payables at the same time. If you want one number, that is a decision somebody has to make and record \u2014 it is not a sum the system is withholding.',
